const STANDALONE_WEBGPU_RAG_MAX_EVIDENCE_TOKENS = 1800;
const STANDALONE_WEBGPU_RAG_MAX_PASSAGE_TOKENS = 420;
const STANDALONE_WEBGPU_RAG_GENERATION_TOKENS = 2048;
